mapper.select:
SELECT user_unit AS unit_name, COUNT(*) AS post_count, SUM(CASE WHEN is_pinned = '1' THEN 1 ELSE 0 END) AS pin_count FROM forum_post WHERE
AND create_time >= #{startDate}
AND create_time <= #{endDate}
AND user_unit = #{unitName}
GROUP BY user_unit ORDER BY post_count DESC

SELECT user_dept AS dept_name, COUNT(*) AS post_count, SUM(CASE WHEN is_pinned = '1' THEN 1 ELSE 0 END) AS pin_count FROM forum_post WHERE
AND user_unit = #{unitName}
AND create_time >= #{startDate}
AND create_time <= #{endDate}
GROUP BY user_dept ORDER BY post_count DESC

SELECT p.user_id AS user_id, u.nickname AS user_name, COUNT(*) AS post_count, SUM(CASE WHEN p.is_pinned = '1' THEN 1 ELSE 0 END) AS pin_count FROM forum_post p LEFT JOIN forum_user u ON p.user_id = u.user_id WHERE p.del_flag = '0' AND p.is_locked = '0' AND p.is_restricted = '0'
AND p.user_unit = #{unitName}
AND p.create_time >= #{startDate}
AND p.create_time <= #{endDate}
GROUP BY p.user_id, u.nickname ORDER BY post_count DESC
